def validate_topics(topics, track_name):
    print(f"Validating {len(topics)} {track_name} topics...")
    assert len(topics) == 100, f"Expected 100 topics for {track_name}, got {len(topics)}"
    for idx, (title, subj, sys_name, focus, ref_name, ref_url) in enumerate(topics, 1):
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in {track_name} #{idx}: {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in {track_name} #{idx}: {title}"
        assert ref_url.startswith("https://"), f"Reference URL must start with https:// in {track_name} #{idx}"
        assert len(focus) > 20, f"Focus too short in {track_name} #{idx}"
    print(f"Validated 100 {track_name} topics successfully.")

def write_topics_b():
    validate_topics(MRCEM_TOPICS, "MRCEM")
    validate_topics(SMLE_TOPICS, "SMLE")
    validate_topics(UHS_TOPICS, "UHS MBBS")

    topics_b_path = os.path.join(os.path.dirname(__file__), "mega67_topics_b.py")
    with open(topics_b_path, "w", encoding="utf-8") as f:
        f.write("# scripts/mega67_topics_b.py\n")
        f.write("# Generated automatically\n\n")
        f.write(f"MRCEM_TOPICS = {repr(MRCEM_TOPICS)}\n\n")
        f.write(f"SMLE_TOPICS = {repr(SMLE_TOPICS)}\n\n")
        f.write(f"UHS_TOPICS = {repr(UHS_TOPICS)}\n")
    print(f"Wrote {topics_b_path} successfully.")

if __name__ == "__main__":
    write_topics_b()
